function validate([grid, health]) {
  const m = grid.length;
  if (m < 1 || m > 50) return 'grid needs 1 to 50 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 50) return 'Each row needs 1 to 50 cells.';
  if (grid.some(row => row.length !== n)) return 'All rows must have the same length.';
  if (m * n < 2) return 'The grid needs at least 2 cells.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Every cell is 0 or 1.';
  if (health < 1 || health > m + n) return 'health is between 1 and m + n.';
  return null;
}

