function findSafeWalk(grid, health) {
  const m = grid.length;
  const n = grid[0].length;
  const lost = Array.from({ length: m }, () => new Array(n).fill(Infinity));
  const moves = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  lost[0][0] = grid[0][0];
  let current = [[0, 0]];
  while (current.length > 0) {
    const next = [];
    for (let i = 0; i < current.length; i++) {
      const [row, col] = current[i];
      for (const [dr, dc] of moves) {
        const r = row + dr;
        const c = col + dc;
        if (r < 0 || r >= m || c < 0 || c >= n) {
          continue;
        }
        const cost = lost[row][col] + grid[r][c];
        if (cost < lost[r][c]) {
          lost[r][c] = cost;
          if (grid[r][c] === 0) {
            current.push([r, c]);
          } else {
            next.push([r, c]);
          }
        }
      }
    }
    current = next;
  }
  return lost[m - 1][n - 1] < health;
}

