function findSafeWalk(grid, health) {
  // Follow the rules literally: search every state (row, column, health left) that a walk can reach.
  const m = grid.length, n = grid[0].length;
  const start = health - grid[0][0];
  if (start <= 0) return false;
  const seen = new Set(['0,0,' + start]);
  const stack = [[0, 0, start]];
  while (stack.length) {
    const [r, c, h] = stack.pop();
    if (r === m - 1 && c === n - 1) return true;
    for (const [a, b] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (a < 0 || b < 0 || a >= m || b >= n) continue;
      const left = h - grid[a][b];
      const key = a + ',' + b + ',' + left;
      if (left >= 1 && !seen.has(key)) {
        seen.add(key);
        stack.push([a, b, left]);
      }
    }
  }
  return false;
}

