function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 35 + Math.floor(rand() * 16) : 1 + Math.floor(rand() * 5);
  const n = large ? 35 + Math.floor(rand() * 16) : (m === 1 ? 2 : 1) + Math.floor(rand() * (m === 1 ? 4 : 5));
  const shape = rand();
  let grid;
  if (shape < 0.3 && m >= 3) {
    // Safe rows joined at alternating ends make a long winding corridor through unsafe walls.
    grid = Array.from({ length: m }, (_, r) => Array.from({ length: n }, (_, c) => r % 2 === 0 || c === (r % 4 === 1 ? n - 1 : 0) ? 0 : 1));
    if (rand() < 0.5) grid[1 + Math.floor(rand() * (m - 1))][Math.floor(rand() * n)] = 1;
  } else {
    const density = shape < 0.45 ? 0.9 : 0.15 + rand() * 0.6;
    grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  }
  // The least possible loss, by relaxation sweeps in alternating directions, puts health on the boundary half the time.
  const loss = grid.map(row => row.map(() => Infinity));
  loss[0][0] = grid[0][0];
  for (let pass = 0, changed = true; changed; pass++) {
    changed = false;
    for (let k = 0; k < m * n; k++) {
      const cell = pass % 2 === 0 ? k : m * n - 1 - k, r = Math.floor(cell / n), c = cell % n;
      for (const [a, b] of [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]) {
        if (a >= 0 && b >= 0 && a < m && b < n && loss[a][b] + grid[r][c] < loss[r][c]) { loss[r][c] = loss[a][b] + grid[r][c]; changed = true; }
      }
    }
  }
  const need = loss[m - 1][n - 1];
  const health = rand() < 0.5 ? Math.min(m + n, Math.max(1, need + (rand() < 0.5 ? 0 : 1))) : 1 + Math.floor(rand() * (m + n));
  return [grid, health];
}
